def execute(arguments):
    """
    压缩文件管理

    参数:
        arguments (dict): 包含以下字段
            - operation (str): 操作类型
                - "create": 创建压缩文件
                - "extract": 解压文件
                - "list": 列出压缩文件内容
            - archive_path (str): 压缩文件路径，必填
            - source_path (str): 源文件/目录路径，create操作必填
            - extract_path (str): 解压目标目录，extract操作可选，默认当前目录

    返回:
        dict: 包含操作结果的字典
            - success (bool): 是否成功
            - archive_path (str): 压缩文件路径
            - files (list): 文件列表（list操作）
            - count (int): 文件数量
            - extracted_path (str): 解压目录（extract操作）
            - error (str): 错误信息（失败时）
    """
    import os
    import zipfile

    operation = arguments.get("operation", "list")
    archive_path = arguments.get("archive_path", "")
    source_path = arguments.get("source_path", "")
    extract_path = arguments.get("extract_path", "")

    if not archive_path:
        return {"success": False, "error": "请提供压缩文件路径"}

    try:
        if operation == "create":
            if not source_path:
                return {"success": False, "error": "请提供源文件/目录路径"}

            if not os.path.exists(source_path):
                return {"success": False, "error": f"源路径不存在: {source_path}"}

            file_count = 0
            with zipfile.ZipFile(archive_path, 'w', zipfile.ZIP_DEFLATED) as zf:
                if os.path.isfile(source_path):
                    zf.write(source_path, os.path.basename(source_path))
                    file_count = 1
                else:
                    for root, dirs, files in os.walk(source_path):
                        for file in files:
                            file_path = os.path.join(root, file)
                            arcname = os.path.relpath(file_path, source_path)
                            zf.write(file_path, arcname)
                            file_count += 1

            return {
                "success": True,
                "archive_path": archive_path,
                "source_path": source_path,
                "count": file_count
            }

        elif operation == "extract":
            if not os.path.exists(archive_path):
                return {"success": False, "error": f"压缩文件不存在: {archive_path}"}

            if not extract_path:
                extract_path = os.path.dirname(archive_path)

            with zipfile.ZipFile(archive_path, 'r') as zf:
                zf.extractall(extract_path)
                file_count = len(zf.namelist())

            return {
                "success": True,
                "archive_path": archive_path,
                "extracted_path": extract_path,
                "count": file_count
            }

        elif operation == "list":
            if not os.path.exists(archive_path):
                return {"success": False, "error": f"压缩文件不存在: {archive_path}"}

            with zipfile.ZipFile(archive_path, 'r') as zf:
                files = []
                for info in zf.infolist():
                    files.append({
                        "name": info.filename,
                        "size": info.file_size,
                        "compressed_size": info.compress_size,
                        "is_dir": info.is_dir()
                    })

            return {
                "success": True,
                "archive_path": archive_path,
                "files": files,
                "count": len(files)
            }

        else:
            return {"success": False, "error": f"未知的操作: {operation}"}
    except zipfile.BadZipFile:
        return {"success": False, "error": "无效的ZIP文件"}
    except Exception as e:
        return {"success": False, "error": f"操作失败: {str(e)}"}
